--criar arquivo .sh de recover
datainicial=`date +%s`

NLS_DATE_FORMAT=DD/MM/YYYY_HH24:MI:SS;  export NLS_DATE_FORMAT

rman target / catalog rman/OraC12345678#@DBMON @/u02/recover_full_kiprev_221124.rman

# Calculo do tempo de execucao..
datafinal=`date +%s`
soma=`expr $datafinal - $datainicial`
resultado=`expr 10800 + $soma`
tempo=`date -d @$resultado +%H:%M:%S`
echo ""
echo "------------------------------------------------------------------------"
echo " Tempo de Execucao backup kiprev : $tempo "


-- fuzzy
ALTER SESSION SET NLS_DATE_FORMAT="YYYY-MM-DD HH24:MI:SS";
SET PAGES 1000
COL FILE# FOR 99999
COL CHECKPOINT_CHANGE# FOR 9999999999999999999999999
COL FUZZY FOR A5
SELECT FILE#,STATUS,CHECKPOINT_TIME,CHECKPOINT_CHANGE#,FUZZY FROM V$DATAFILE_HEADER order by 1;